const x=$json, allowed=['facebook','whatsapp','instagram','internal'];
if(!allowed.includes(x.channel)) throw new Error('identity_invalid_channel');
for(const k of ['external_user_id','conversation_external_id','turn_id'])
 if(typeof x[k]!=='string'||!x[k].trim()) throw new Error(`identity_missing_${k}`);
return [{json:{...x,external_user_id:x.external_user_id.trim(),conversation_external_id:x.conversation_external_id.trim(),turn_id:x.turn_id.trim()}}];

const input=$('Validate Identity Input').first().json;
const row=Array.isArray($json)?$json[0]:$json;
if(!row?.customer_id||!row?.identity_id) throw new Error('identity_resolution_failed');
return [{json:{customer_id:row.customer_id,identity_id:row.identity_id,identity_level:Number(row.identity_level??1),channel:input.channel,external_user_id:input.external_user_id,conversation_external_id:input.conversation_external_id,turn_id:input.turn_id,created_customer:Boolean(row.created_customer),authorization_basis:'trusted_channel_identity'}}];

const x=$json;
if(!Number.isInteger(x.identity_level)||x.identity_level<0||x.identity_level>3) throw new Error('identity_invalid_level');
if(!x.customer_id) throw new Error('identity_missing_customer');
return [{json:x}];
